draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 20 + 20*Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 80 + 20*Math.sin(t), H/2 + 70);
  ctx.stroke();
  // sniffing
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2 + 70);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t) + 10*Math.cos(3*t), H/2 + 90);
  ctx.stroke();
  // missing person
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 10*Math.sin(2*t), H/2 + 100, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 10*Math.sin(2*t), H/2 + 110);
  ctx.lineTo(W/2 - 100 + 10*Math.sin(2*t), H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 10*Math.sin(2*t), H/2 + 130);
  ctx.lineTo(W/2 - 120 + 10*Math.sin(2*t), H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 10*Math.sin(2*t), H/2 + 130);
  ctx.lineTo(W/2 - 80 + 10*Math.sin(2*t), H/2 + 150);
  ctx.stroke();
  ctx.restore();
}
